fn rsplit(a: Vec<String>, sep: String, maxsplit: u8) -> Vec<Vec<String>> {
    // Convert separator to &str once
    let sep = sep.as_str();
    // Convert maxsplit to usize; we'll ask for up to maxsplit+1 parts
    let maxsplit = maxsplit as usize;

    a.into_iter()
        .map(|s| {
            // Perform at most maxsplit splits from the right, producing up to maxsplit+1 parts
            let mut parts: Vec<String> = s
                .rsplitn(maxsplit + 1, sep)
                .map(|fragment| fragment.to_string())
                .collect();
            // rsplitn yields parts starting from the rightmost slice, so reverse to restore left-to-right order
            parts.reverse();
            parts
        })
        .collect()
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn test_basic() {
        let input = vec![
            "a-b-c-d".to_string(),
            "one:two:three".to_string(),
            "".to_string(),
            "nosplit".to_string(),
        ];
        let sep = "-".to_string();
        let result = rsplit(input.clone(), sep.clone(), 2);
        assert_eq!(
            result,
            vec![
                vec!["a-b".to_string(), "c".to_string(), "d".to_string()],
                vec!["one:two:three".to_string()], // separator "-" doesn't appear
                vec!["".to_string()],
                vec!["nosplit".to_string()],
            ]
        );

        // Test with colon separator, maxsplit = 1
        let result = rsplit(input, ":".to_string(), 1);
        assert_eq!(
            result,
            vec![
                vec!["a-b-c-d".to_string()],
                vec!["one:two".to_string(), "three".to_string()],
                vec!["".to_string()],
                vec!["nosplit".to_string()],
            ]
        );
    }

    #[test]
    fn test_no_splits_when_zero() {
        let input = vec!["x-y-z".to_string(), "".to_string()];
        let result = rsplit(input, "-".to_string(), 0);
        assert_eq!(
            result,
            vec![vec!["x-y-z".to_string()], vec!["".to_string()],]
        );
    }

    #[test]
    fn test_more_splits_than_occurrences() {
        let input = vec!["a-b-c".to_string()];
        // There are only 2 separators, but we ask for up to 5 splits.
        let result = rsplit(input, "-".to_string(), 5);
        assert_eq!(
            result,
            vec![vec!["a".to_string(), "b".to_string(), "c".to_string()]]
        );
    }
}